<?php $types=['supplier'=>'مورد','subcontractor'=>'مقاول باطن','both'=>'مورد ومقاول باطن'];$vendorId=(int)$vendor['id']; ?>
<div class="page-header mb-4"><div class="row align-items-center"><div class="col"><div class="page-pretitle"><?=e($vendor['vendor_code'])?></div><h2 class="page-title"><?=e($vendor['name'])?></h2></div><div class="col-auto d-flex gap-2"><?php if($canEdit):?><a class="btn btn-primary" href="/vendors/<?=$vendorId?>/edit"><i class="ti ti-edit ms-2"></i>تعديل</a><?php endif;?><a class="btn" href="/vendors">العودة</a></div></div></div>
<div class="row g-4"><div class="col-lg-5"><div class="card"><div class="card-header"><h3 class="card-title">بيانات المورد</h3></div><div class="card-body"><dl class="row mb-0"><?php foreach(['vendor_code'=>'كود المورد','vendor_type'=>'النوع','tax_number'=>'الرقم الضريبي','commercial_registration'=>'السجل التجاري','phone'=>'الهاتف','mobile'=>'المحمول','email'=>'البريد الإلكتروني','address'=>'العنوان'] as $key=>$label):?><dt class="col-5 mb-2"><?=e($label)?></dt><dd class="col-7 mb-2"><?=e($key==='vendor_type'?($types[$vendor[$key]]??'—'):($vendor[$key]?:'—'))?></dd><?php endforeach;?><dt class="col-5">الحالة</dt><dd class="col-7"><span class="badge <?=$vendor['is_active']?'bg-green-lt':'bg-secondary-lt'?>"><?=$vendor['is_active']?'نشط':'غير نشط'?></span></dd></dl></div></div></div><div class="col-lg-7"><div class="card"><div class="card-header"><h3 class="card-title">جهات الاتصال</h3><?php if($canEdit):?><div class="card-actions"><button class="btn btn-sm btn-primary" id="add-vendor-contact" type="button"><i class="ti ti-plus ms-1"></i>إضافة</button></div><?php endif;?></div><div id="vendor-contacts" data-vendor-id="<?=$vendorId?>"><?=$this->component('vendor-contacts',['vendorId'=>$vendorId,'contacts'=>$contacts,'canEdit'=>$canEdit,'csrfToken'=>$csrfToken])?></div></div></div></div>
<?php if($canActivate):?><div class="mt-4"><form class="js-confirm-form" data-confirm="هل تريد <?=$vendor['is_active']?'تعطيل':'تفعيل'?> هذا المورد؟" method="post" action="/vendors/<?=$vendorId?>/activate"><input type="hidden" name="_token" value="<?=e($csrfToken)?>"><input type="hidden" name="active" value="<?=$vendor['is_active']?'0':'1'?>"><button class="btn <?=$vendor['is_active']?'btn-outline-danger':'btn-success'?>" type="submit"><?=$vendor['is_active']?'تعطيل المورد':'تفعيل المورد'?></button></form></div><?php endif;?>
<div class="card mt-4"><div class="card-header"><h3 class="card-title">مجالات العمل</h3><span class="badge bg-blue-lt me-auto"><?=count($workSections)?> مجال</span></div><div class="card-body"><?php if($workSections===[]):?><div class="text-secondary">لم تُحدد مجالات عمل لهذا المورد.</div><?php else:?><div class="d-flex flex-wrap gap-2"><?php foreach($workSections as $section):?><span class="badge bg-azure-lt fs-4 fw-normal"><?=e($section['section_code'])?> — <?=e($section['name'])?><?=(int)$section['is_active']===1?'':' (غير نشط)'?></span><?php endforeach;?></div><?php endif;?></div></div>
